command:
mkdir -p /work/tmp/review/api/src
cat > /work/tmp/review/api/Cargo.toml <<'EOF'
[package]
name = "just-review-api"
version = "0.0.0"
edition = "2024"
publish = false

[dependencies]
just = { path = "/work/crate" }
EOF
cat > /work/tmp/review/api/src/lib.rs <<'EOF'
//! Ordinary public API checks for the local review.

#[cfg(test)]
mod tests {
    use std::path::Path;

    #[test]
    fn invalid_datetime_returns_error() {
        assert!(
            just::run([
                "just",
                "--justfile",
                "/work/tmp/review/datetime/justfile",
                "--evaluate",
                "x",
            ]
            .into_iter())
            .is_err()
        );
    }

    #[test]
    fn valid_datetime_succeeds() {
        assert!(
            just::run([
                "just",
                "--justfile",
                "/work/tmp/review/api/valid.just",
                "--evaluate",
                "x",
            ]
            .into_iter())
            .is_ok()
        );
    }

    #[test]
    fn invalid_regex_returns_error() {
        assert!(
            just::run([
                "just",
                "--justfile",
                "/work/tmp/review/api/regex.just",
                "--evaluate",
                "x",
            ]
            .into_iter())
            .is_err()
        );
    }

    #[test]
    fn summary_returns_parse_error() {
        let result = just::summary::summary(Path::new("/work/tmp/review/api/invalid.just"))
            .expect("reading an existing local fixture should succeed");
        assert!(result.is_err());
    }

    #[test]
    fn unindent_preserves_unicode() {
        assert_eq!(just::unindent("\n  café\n  🤖\n"), "café\n🤖\n");
    }
}
EOF
cat > /work/tmp/review/api/valid.just <<'EOF'
x := datetime('%Y')
EOF
cat > /work/tmp/review/api/regex.just <<'EOF'
x := replace_regex('value', '[', 'replacement')
EOF
cat > /work/tmp/review/api/invalid.just <<'EOF'
x :=
EOF
cd /work/tmp/review/api
export RUSTUP_AUTO_INSTALL=0 CARGO_NET_OFFLINE=true
cargo test --offline > /work/api-test.log 2>&1
api_status=$?
printf 'api-test=%s\n' "$api_status"
tail -35 /work/api-test.log
cargo fmt --all --check > /work/api-fmt.log 2>&1
printf 'api-fmt=%s\n' "$?"
cat /work/api-fmt.log
/work/clock
